{
	"name": "@jeffreyjyz/opencode-shell-rc",
	"version": "0.5.1",
	"description": "Make the opencode agent shell load your zsh aliases and functions (via a fast ZDOTDIR shim), without paying for oh-my-zsh/compinit on every command.",
	"type": "module",
	"main": "dist/index.js",
	"types": "dist/index.d.ts",
	"exports": {
		".": "./dist/index.js"
	},
	"bin": {
		"shell-rc-migrate": "dist/migrate.js"
	},
	"scripts": {
		"build": "rm -rf dist && bun build src/index.ts src/migrate.ts --outdir dist --target bun --external @opencode/plugin && tsc -p tsconfig.build.json",
		"test": "bun test",
		"lint": "biome lint --write .",
		"typecheck": "bun check"
	},
	"devDependencies": {
		"@opencode/plugin": "^2.0.11",
		"@types/bun": "latest",
		"cac": "^7.0.0",
		"typescript": "^7"
	},
	"files": [
		"dist",
		"index.js",
		"LICENSE"
	],
	"keywords": [
		"opencode",
		"opencode-plugin",
		"zsh",
		"zdotdir",
		"aliases"
	],
	"license": "MIT",
	"repository": {
		"type": "git",
		"url": "git+https://github.com/JeffreyJYZ/cmdcode-tools.git",
		"directory": "opencode-shell-rc"
	},
	"homepage": "https://github.com/JeffreyJYZ/cmdcode-tools/tree/main/opencode-shell-rc#readme",
	"bugs": {
		"url": "https://github.com/JeffreyJYZ/cmdcode-tools/issues"
	},
	"publishConfig": {
		"access": "public"
	}
}

// Entry shim for local/directory plugin loading: opencode resolves the server
// half as `index.js`/`server.js` beside the package root (package `exports` are
// only consulted for npm-installed plugins). Keep in sync with ./dist output.
export { default } from "./dist/index.js";

// @bun
// src/constants/shell-rc.ts
var SHELL_RC_ID = "opencode-shell-rc";
var CAPTURE_MARKER = "__opencode_shell_rc_capture__";
var STATE_VERSION = 2;
var LINKED = [".zshrc", ".zprofile", ".zlogin"];
var AGENTS_FILE = "AGENTS.md";
var ALIAS_BLOCK_BEGIN = "<!-- shell-rc-aliases-begin -->";
var ALIAS_BLOCK_END = "<!-- shell-rc-aliases-end -->";
var GUARDS_FILE = "guards.zsh";
var SHELL_RC_CONFIG = "shell-rc.json";
var ENV_FILE = "env.zsh";
var DEFAULT_BLOCKED = {};

// src/shim.ts
import { execFileSync as execFileSync2 } from "child_process";
import {
  existsSync as existsSync4,
  lstatSync,
  mkdirSync as mkdirSync4,
  readFileSync as readFileSync4,
  renameSync as renameSync4,
  rmSync as rmSync3,
  statSync,
  symlinkSync,
  writeFileSync as writeFileSync4
} from "fs";
import { homedir as homedir4 } from "os";
import { join as join4 } from "path";

// src/aliases.ts
import { execFileSync } from "child_process";
import { existsSync, mkdirSync, readFileSync, renameSync, writeFileSync } from "fs";
import { homedir } from "os";
import { dirname, join } from "path";
var home = () => process.env.HOME ?? homedir();
function rcFile() {
  return join(home(), ".zshrc");
}
function agentsFile() {
  const config = process.env.XDG_CONFIG_HOME ?? join(home(), ".config");
  return join(config, "opencode", AGENTS_FILE);
}
function aliasCommands(rc) {
  const commands = [];
  for (const line of rc.split(`
`)) {
    const match = line.match(/^\s*alias\s+(.+?)\s*$/);
    if (!match)
      continue;
    const body = match[1];
    if (!body || body.startsWith("#"))
      continue;
    commands.push(`alias ${body}`);
  }
  return commands;
}
function parseAliasListing(output) {
  const aliases = [];
  for (const line of output.split(`
`)) {
    if (!line.startsWith("alias "))
      continue;
    let rest = line.slice("alias ".length);
    for (;; ) {
      const option = rest.match(/^(-[A-Za-z]+|--)\s+/);
      if (!option)
        break;
      rest = rest.slice(option[0].length);
    }
    const equals = rest.indexOf("=");
    if (equals <= 0)
      continue;
    aliases.push({
      name: rest.slice(0, equals),
      value: unquote(rest.slice(equals + 1).trim())
    });
  }
  return aliases;
}
function unquote(raw) {
  if (raw.length < 2 || !raw.startsWith("'") || !raw.endsWith("'"))
    return raw;
  return raw.slice(1, -1).replaceAll("'\\''", "'");
}
function normalize(commands) {
  if (commands.length === 0)
    return [];
  const script = `unalias -m '*' 2>/dev/null
${commands.join(`
`)}
alias -L`;
  let output;
  try {
    output = execFileSync("zsh", ["-f", "-c", script], {
      encoding: "utf8",
      stdio: ["ignore", "pipe", "ignore"],
      env: { ...process.env, ZDOTDIR: home() },
      timeout: 20000
    });
  } catch {
    return [];
  }
  return parseAliasListing(output);
}
function renderBlock(aliases) {
  const lines = [
    ALIAS_BLOCK_BEGIN,
    "## Shell aliases (auto-generated from ~/.zshrc)",
    "",
    "Regenerated by `opencode-shell-rc` when the rc changes \u2014 edits inside this block are overwritten.",
    "",
    ...aliases.map((alias) => `- \`${alias.name}\` = \`${alias.value}\``),
    ALIAS_BLOCK_END
  ];
  return lines.join(`
`);
}
function upsertBlock(text, block) {
  const begin = text.indexOf(ALIAS_BLOCK_BEGIN);
  const end = begin < 0 ? -1 : text.indexOf(ALIAS_BLOCK_END, begin);
  if (begin >= 0 && end >= 0) {
    return text.slice(0, begin) + block + text.slice(end + ALIAS_BLOCK_END.length);
  }
  const base = text.replace(/\s+$/, "");
  return base.length > 0 ? `${base}

${block}
` : `${block}
`;
}
function syncAliases() {
  let rc;
  try {
    rc = readFileSync(rcFile(), "utf8");
  } catch {
    return false;
  }
  const block = renderBlock(normalize(aliasCommands(rc)));
  const path = agentsFile();
  let current = "";
  try {
    current = readFileSync(path, "utf8");
  } catch {}
  const next = upsertBlock(current, block);
  if (next === current)
    return false;
  try {
    mkdirSync(dirname(path), { recursive: true });
    const temporary = `${path}.tmp`;
    writeFileSync(temporary, next);
    renameSync(temporary, path);
  } catch {
    return false;
  }
  return true;
}
function hasBlock(path) {
  if (!existsSync(path))
    return false;
  return readFileSync(path, "utf8").includes(ALIAS_BLOCK_BEGIN);
}

// src/env.ts
import { existsSync as existsSync3, mkdirSync as mkdirSync3, readFileSync as readFileSync3, renameSync as renameSync3, rmSync as rmSync2, writeFileSync as writeFileSync3 } from "fs";
import { homedir as homedir3 } from "os";
import { join as join3 } from "path";

// src/guards.ts
import {
  accessSync,
  constants,
  existsSync as existsSync2,
  mkdirSync as mkdirSync2,
  readFileSync as readFileSync2,
  renameSync as renameSync2,
  rmSync,
  writeFileSync as writeFileSync2
} from "fs";
import { homedir as homedir2 } from "os";
import { join as join2 } from "path";
var home2 = () => process.env.HOME ?? homedir2();
function configFile() {
  const config = process.env.XDG_CONFIG_HOME ?? join2(home2(), ".config");
  return join2(config, "opencode", SHELL_RC_CONFIG);
}
function normalizeBlocked(value) {
  const entries = [];
  if (Array.isArray(value)) {
    for (const item of value) {
      if (!item || typeof item !== "object" || Array.isArray(item))
        continue;
      const raw = item;
      if (typeof raw.name !== "string" || !raw.name.trim())
        continue;
      const entry = { name: raw.name.trim() };
      if (typeof raw.alternative === "string" && raw.alternative.trim()) {
        entry.alternative = raw.alternative.trim();
      }
      if (typeof raw.reason === "string" && raw.reason.trim()) {
        entry.reason = raw.reason.trim();
      }
      if (entry.alternative || entry.reason)
        entries.push(entry);
    }
  } else if (value && typeof value === "object") {
    for (const [name, replacement] of Object.entries(value)) {
      if (typeof replacement !== "string" || !replacement.trim())
        continue;
      entries.push({ name: name.trim(), alternative: replacement.trim() });
    }
  }
  const byName = new Map;
  for (const entry of entries) {
    byName.delete(entry.name);
    byName.set(entry.name, entry);
  }
  return [...byName.values()];
}
function loadConfig() {
  try {
    const parsed = JSON.parse(readFileSync2(configFile(), "utf8"));
    return { blocked: normalizeBlocked(parsed.blocked) };
  } catch {
    return { blocked: normalizeBlocked(DEFAULT_BLOCKED) };
  }
}
function resolves(command) {
  const path = process.env.PATH ?? "";
  for (const dir of path.split(":")) {
    if (!dir)
      continue;
    try {
      accessSync(join2(dir, command), constants.X_OK);
      return true;
    } catch {}
  }
  return false;
}
function validName(name) {
  return /^[A-Za-z0-9._+-]+$/.test(name);
}
function escapeZshDoubleQuoted(text) {
  return text.replace(/[\\"$`]/g, (character) => `\\${character}`);
}
function renderGuards(blocked, installed = resolves) {
  const lines = ["# Generated by opencode-shell-rc. Sourced by agent shells only."];
  for (const entry of normalizeBlocked(blocked)) {
    const { name } = entry;
    if (!validName(name))
      continue;
    if (name === "cat")
      continue;
    const alternative = entry.alternative ?? "";
    const reason = entry.reason ?? "";
    let instruction = "";
    if (alternative) {
      const binary = alternative.split(/\s+/)[0] ?? "";
      if (installed(binary)) {
        instruction = `use ${alternative}${reason ? ` (${reason})` : ""}`;
      } else {
        instruction = reason || alternative;
      }
    } else if (reason) {
      instruction = reason;
    }
    if (!instruction)
      continue;
    const message = escapeZshDoubleQuoted(`${name} is blocked in agent shells \u2014 ${instruction}`);
    lines.push(`unalias ${name} 2>/dev/null`, `function ${name} {`, `  print -r -u2 -- "${message}"`, "  return 127", "}");
  }
  return `${lines.join(`
`)}
`;
}
function syncGuards(installed = resolves) {
  const script = renderGuards(loadConfig().blocked, installed);
  const path = join2(stateDirPath(), GUARDS_FILE);
  const wanted = script.includes("function ") ? script : undefined;
  if (!wanted) {
    if (!existsSync2(path))
      return false;
    try {
      rmSync(path, { force: true });
      return true;
    } catch {
      return false;
    }
  }
  let current = "";
  try {
    current = readFileSync2(path, "utf8");
  } catch {}
  if (current === wanted)
    return false;
  try {
    mkdirSync2(stateDirPath(), { recursive: true });
    const temporary = `${path}.tmp`;
    writeFileSync2(temporary, wanted);
    renameSync2(temporary, path);
  } catch {
    return false;
  }
  return true;
}
function stateDirPath() {
  const base = process.env.XDG_STATE_HOME ?? join2(home2(), ".local", "state");
  return join2(base, "opencode", "shell-rc");
}

// src/env.ts
var home3 = () => process.env.HOME ?? homedir3();
var VALID_NAME = /^[A-Za-z_][A-Za-z0-9_]*$/;
function loadEnv() {
  try {
    const parsed = JSON.parse(readFileSync3(configFile(), "utf8"));
    const values = {};
    if (parsed.env && typeof parsed.env === "object") {
      for (const [name, value] of Object.entries(parsed.env)) {
        if (!VALID_NAME.test(name) || typeof value !== "string")
          continue;
        values[name] = value;
      }
    }
    return values;
  } catch {
    return {};
  }
}
function quote(value) {
  return `'${value.replaceAll("'", `'\\''`)}'`;
}
function renderEnv(values) {
  const lines = ["# Generated by opencode-shell-rc. Sourced by agent shells only."];
  for (const [name, value] of Object.entries(values)) {
    lines.push(`export ${name}=${quote(value)}`);
  }
  return `${lines.join(`
`)}
`;
}
function syncEnv() {
  const script = renderEnv(loadEnv());
  const path = join3(stateDirPath2(), ENV_FILE);
  const wanted = script.includes("export ") ? script : undefined;
  if (!wanted) {
    if (!existsSync3(path))
      return false;
    try {
      rmSync2(path, { force: true });
      return true;
    } catch {
      return false;
    }
  }
  let current = "";
  try {
    current = readFileSync3(path, "utf8");
  } catch {}
  if (current === wanted)
    return false;
  try {
    mkdirSync3(stateDirPath2(), { recursive: true });
    const temporary = `${path}.tmp`;
    writeFileSync3(temporary, wanted);
    renameSync3(temporary, path);
    return true;
  } catch {
    return false;
  }
}
function stateDirPath2() {
  const base = process.env.XDG_STATE_HOME ?? join3(home3(), ".local", "state");
  return join3(base, "opencode", "shell-rc");
}

// src/shim.ts
var home4 = () => process.env.HOME ?? homedir4();
function stateDir() {
  const base = process.env.XDG_STATE_HOME ?? join4(home4(), ".local", "state");
  return join4(base, "opencode", "shell-rc");
}
function shimFile() {
  return join4(stateDir(), ".zshenv");
}
function stateFile() {
  return join4(stateDir(), "state.zsh");
}
function stateVersionFile() {
  return `${stateFile()}.version`;
}
function shimContent() {
  return [
    "# Generated by opencode-shell-rc. Sourced by every zsh the agent runs.",
    '[[ -f "$HOME/.zshenv" ]] && source "$HOME/.zshenv"',
    'if [[ ! -o interactive && -n "$ZDOTDIR" && -f "$ZDOTDIR/state.zsh" ]]; then source "$ZDOTDIR/state.zsh"; fi',
    'if [[ ! -o interactive && -n "$ZDOTDIR" && -f "$ZDOTDIR/env.zsh" ]]; then source "$ZDOTDIR/env.zsh"; fi',
    'if [[ ! -o interactive && -n "$ZDOTDIR" && -f "$ZDOTDIR/guards.zsh" ]]; then source "$ZDOTDIR/guards.zsh"; fi',
    '[[ -f "$HOME/.config/opencode/shell.zsh" ]] && source "$HOME/.config/opencode/shell.zsh"',
    ""
  ].join(`
`);
}
function isZsh(shell) {
  return /(^|[\\/])zsh(\.exe)?$/.test(shell);
}
function sourceFiles() {
  return [
    join4(home4(), ".zshrc"),
    join4(home4(), ".zshenv"),
    join4(home4(), ".oh-my-zsh", "oh-my-zsh.sh")
  ].filter((file) => existsSync4(file));
}
function needsRefresh(stateMtime, sourceMtimes, stateVersion) {
  if (stateMtime === undefined)
    return true;
  if (stateVersion !== STATE_VERSION)
    return true;
  return sourceMtimes.some((mtime) => mtime > stateMtime);
}
function capture() {
  const output = execFileSync2("zsh", ["-ic", `print -r -- ${CAPTURE_MARKER}; alias -L; typeset -f`], {
    encoding: "utf8",
    stdio: ["ignore", "pipe", "ignore"],
    env: { ...process.env, ZDOTDIR: home4() },
    timeout: 20000
  });
  const at = output.indexOf(CAPTURE_MARKER);
  if (at < 0)
    return;
  return output.slice(at + CAPTURE_MARKER.length).replace(/^[\r\n]+/, "");
}
function refreshIfStale() {
  const state = stateFile();
  const stateMtime = existsSync4(state) ? statSync(state).mtimeMs : undefined;
  const sourceMtimes = sourceFiles().map((file) => statSync(file).mtimeMs);
  const stateVersion = readStateVersion();
  if (!needsRefresh(stateMtime, sourceMtimes, stateVersion))
    return false;
  let output;
  try {
    output = capture();
  } catch {
    return false;
  }
  if (output === undefined)
    return false;
  const temporary = `${state}.tmp`;
  writeFileSync4(temporary, `# Generated by opencode-shell-rc. Do not edit.
${output}
`);
  renameSync4(temporary, state);
  writeFileSync4(stateVersionFile(), `${STATE_VERSION}
`);
  compile(state);
  return true;
}
function readStateVersion() {
  try {
    const raw = readFileSync4(stateVersionFile(), "utf8").trim();
    const value = Number.parseInt(raw, 10);
    return Number.isFinite(value) ? value : undefined;
  } catch {
    return;
  }
}
function compile(state) {
  try {
    rmSync3(`${state}.zwc`, { force: true });
    execFileSync2("zsh", ["-c", 'zcompile "$1"', "zsh", state], {
      stdio: ["ignore", "ignore", "ignore"],
      env: { ...process.env, ZDOTDIR: home4() },
      timeout: 20000
    });
  } catch {}
}
function prepare() {
  mkdirSync4(stateDir(), { recursive: true });
  const shim = shimFile();
  const content = shimContent();
  if (!existsSync4(shim) || readFileSync4(shim, "utf8") !== content) {
    writeFileSync4(shim, content);
  }
  for (const name of LINKED) {
    const source = join4(home4(), name);
    if (!existsSync4(source))
      continue;
    const link = join4(stateDir(), name);
    try {
      lstatSync(link);
      continue;
    } catch {}
    try {
      symlinkSync(source, link);
    } catch {}
  }
  const refreshed = refreshIfStale();
  if (refreshed || !hasBlock(agentsFile())) {
    try {
      syncAliases();
    } catch {}
  }
  try {
    syncGuards();
  } catch {}
  try {
    syncEnv();
  } catch {}
}

// src/index.ts
var shellRcPlugin = {
  id: SHELL_RC_ID,
  async setup(ctx) {
    try {
      prepare();
    } catch {}
    await ctx.shell.hook("create.before", (event) => {
      if (!isZsh(event.shell))
        return;
      try {
        prepare();
        event.env.ZDOTDIR = stateDir();
      } catch {}
    });
  }
};
var src_default = shellRcPlugin;
export {
  src_default as default,
  shellRcPlugin
};
